import csv
import sys
from collections import defaultdict


def load(path):
    totals = defaultdict(float)
    with open(path, newline="") as fh:
        for row in csv.DictReader(fh):
            region = row["region"].strip().lower()
            try:
                totals[region] += float(row["amount"])
